// Accepts either a Gmail Trigger item (simple: false) or the sample enquiry from the test path.
const settings = $('Firm settings').first().json;

return $input.all().map((item) => {
  const j = item.json;
  const fromAddress = j.from?.value?.[0]?.address || j.fromEmail || '';
  const fromName = j.from?.value?.[0]?.name || j.fromName || '';
  const body = (j.text || j.body || j.textAsHtml || '').toString().trim();

  return {
    json: {
      messageId: j.id || j.messageId || null,
      threadId: j.threadId || null,
      receivedAt: j.date ? new Date(j.date).toISOString() : new Date().toISOString(),
      fromAddress,
      fromName,
      subject: j.subject || '(no subject)',
      // Cap the text sent to the model; intake emails rarely need more.
      enquiryText: body.slice(0, settings.maxEnquiryChars || 6000),
      isTest: Boolean(j.isTest),
    },
  };
});

