// HARD STOP 1: conflict check runs in code, before any facts are collected or shared.
// The AI only extracts names; the match decision is deterministic and auditable.
const enquiries = $('Normalise enquiry').all();
const extracted = $('Extract parties and dates').all();
const register = $('Read conflict register').all()
  .map((r) => r.json)
  .filter((r) => r && (r.name || r.Name));

const SUFFIXES = /\b(llc|l\.l\.c|inc|incorporated|ltd|limited|corp|corporation|co|company|plc|llp|lp|pllc|pc|the)\b/g;
const norm = (s) => (s || '')
  .toString()
  .toLowerCase()
  .normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9\s]/g, ' ')
  .replace(SUFFIXES, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Two names match if they are identical after normalising, or if one has 2+ words
// and every word of it appears in the other ("John A. Smith" vs "John Smith").
function namesMatch(a, b) {
  const x = norm(a);
  const y = norm(b);
  if (!x || !y) return false;
  if (x === y) return true;
  const xs = x.split(' ');
  const ys = y.split(' ');
  const [shorter, longer] = xs.length <= ys.length ? [xs, ys] : [ys, xs];
  return shorter.length >= 2 && shorter.every((t) => longer.includes(t));
}

const registerNames = register.map((r) => {
  const aliases = (r.aliases || r.Aliases || '').toString().split(/[;,]/).map((s) => s.trim()).filter(Boolean);
  return {
    names: [r.name || r.Name, ...aliases],
    relationship: r.relationship || r.Relationship || 'unknown',
    matterRef: r.matter_ref || r['Matter ref'] || '',
  };
});

return enquiries.map((enq, i) => {
  const ex = extracted[i]?.json?.output || {};
  const people = [
    { role: 'prospective client', name: ex.prospectName },
    { role: 'prospective client company', name: ex.prospectCompany },
    ...(ex.opposingParties || []).map((name) => ({ role: 'opposing party', name })),
    ...(ex.otherParties || []).map((name) => ({ role: 'other party', name })),
  ].filter((p) => p.name);

  const hits = [];
  for (const p of people) {
    for (const r of registerNames) {
      const matched = r.names.find((n) => namesMatch(p.name, n));
      if (matched) {
        hits.push({ enquiryName: p.name, enquiryRole: p.role, registerName: matched, relationship: r.relationship, matterRef: r.matterRef });
      }
    }
  }

  return {
    json: {
      ...enq.json,
      extracted: ex,
      partiesChecked: people.length,
      registerSize: register.length,
      conflict: hits.length > 0,
      conflictHits: hits,
    },
  };
});

// Conflict hold: staff get the match details; the prospect gets nothing automated.
return $input.all().map((item) => {
  const c = item.json;
  const lines = c.conflictHits.map((h) => `• ${h.enquiryName} (${h.enquiryRole}) matches register entry "${h.registerName}" [${h.relationship}${h.matterRef ? ', ' + h.matterRef : ''}]`);
  return { json: {
    slackText: `:no_entry: *Conflict hold*${c.isTest ? ' [TEST]' : ''}: intake from ${c.fromName || c.fromAddress} was stopped before any facts were collected.\n${lines.join('\n')}\nNo acknowledgement was sent. Clear the conflict manually before anyone replies.`,
    log: { received_at: c.receivedAt, from: c.fromAddress, subject: c.subject, matter_type: c.extracted.matterType,
           conflict: 'HOLD', limitation_status: '', limitation_deadline: '', priority: 'high', advice_flags: 0, outcome: 'conflict_hold' },
  } };
});

// HARD STOP 2: limitation screening runs in code, never in the model.
// EXAMPLE periods only. Replace them with the rules your attorneys sign off for your
// jurisdiction. null = no general limitation period to screen for.
const settings = $('Firm settings').first().json;
const LIMITATION_RULES = {
  personal_injury:   { years: 2,  label: '2 years from date of injury' },
  employment:        { days: 180, label: '180 days to file an agency charge' },
  business_contract: { years: 4,  label: '4 years from breach' },
  real_estate:       { years: 4,  label: '4 years (contract-based claims)' },
  estate_probate:    { years: 4,  label: '4 years from death to probate a will' },
  family_law:        null,
  criminal_defense:  null,
  other:             null,
};

const warnDays = Number(settings.limitationWarningDays) || 90;
const DAY = 24 * 60 * 60 * 1000;

return $input.all().map((item) => {
  const j = item.json;
  const ex = j.extracted || {};
  const rule = LIMITATION_RULES[ex.matterType] ?? null;
  const incident = ex.keyDate ? new Date(ex.keyDate + 'T00:00:00Z') : null;
  const validDate = incident && !isNaN(incident.getTime());

  let status = 'not_applicable';
  let deadline = null;
  let daysLeft = null;

  if (rule && !validDate) {
    status = 'date_unknown';
  } else if (rule && validDate) {
    const d = new Date(incident.getTime());
    if (rule.years) d.setUTCFullYear(d.getUTCFullYear() + rule.years);
    if (rule.days) d.setUTCDate(d.getUTCDate() + rule.days);
    deadline = d.toISOString().slice(0, 10);
    daysLeft = Math.floor((d.getTime() - Date.now()) / DAY);
    if (daysLeft < 0) status = 'expired';
    else if (daysLeft <= warnDays) status = 'urgent';
    else status = 'ok';
  }

  // An approximate date near the line is treated as urgent, not ok.
  if (status === 'ok' && ex.keyDateConfidence === 'approximate' && daysLeft <= warnDays * 2) {
    status = 'urgent';
  }

  return {
    json: {
      ...j,
      limitation: {
        status,
        rule: rule ? rule.label : 'none screened',
        deadline,
        daysLeft,
        jurisdictionNote: settings.jurisdiction,
      },
      priority: status === 'urgent' || status === 'date_unknown' ? 'high' : 'normal',
    },
  };
});

// Possible expired limitation: route straight to an attorney, no automated reply.
return $input.all().map((item) => {
  const c = item.json; const l = c.limitation;
  return { json: {
    slackText: `:hourglass: *Limitation review needed*${c.isTest ? ' [TEST]' : ''}: ${c.fromName || c.fromAddress} (${c.extracted.matterType}). Key date ${c.extracted.keyDate} (${c.extracted.keyDateConfidence}); screening rule "${l.rule}" puts the deadline at ${l.deadline}, ${Math.abs(l.daysLeft)} days ago. An attorney must decide (tolling, discovery rule, other claims) before anyone replies. No acknowledgement was sent.`,
    log: { received_at: c.receivedAt, from: c.fromAddress, subject: c.subject, matter_type: c.extracted.matterType,
           conflict: 'clear', limitation_status: 'expired', limitation_deadline: l.deadline, priority: 'high', advice_flags: 0, outcome: 'attorney_review_limitation' },
  } };
});

