// HARD STOP 3: advice boundary.
// Nothing the model writes is ever sent to the prospective client. The client only gets a
// fixed acknowledgement written by the firm. The model's brief goes to staff, and any
// sentence that reads like legal advice is flagged for the reviewing attorney.
const settings = $('Firm settings').first().json;

const ADVICE_PATTERNS = [
  /\byou (should|must|need to|ought to)\b/i,
  /\byou (have|don't have|do not have) a (strong |good |valid )?(case|claim)\b/i,
  /\b(you will|you'll) (win|lose|recover|be awarded)\b/i,
  /\bguarantee/i,
  /\bwe (can|will) (win|get you)\b/i,
];
const flagAdvice = (text) => ADVICE_PATTERNS.some((re) => re.test(text || ''));

return $input.all().map((item, i) => {
  // Pair each brief with the case it came from (expired cases never reach the agent).
  const c = $('Limitation check (code)').itemMatching(i).json;
  const brief = item.json.output || {};
  const lim = c.limitation;

  const questions = (brief.questionsForCall || []).filter(Boolean);
  const flagged = [brief.summary, ...(brief.keyFacts || []), ...questions].filter(flagAdvice);

  const priority = c.priority === 'high' || brief.priority === 'high' ? 'high' : (brief.priority || 'normal');
  const icon = priority === 'high' ? ':rotating_light:' : ':inbox_tray:';

  const slackText = [
    `${icon} *New intake: ${brief.matterTypeLabel || c.extracted.matterType}* (${priority} priority)${c.isTest ? ' [TEST]' : ''}`,
    `*From:* ${c.fromName || 'Unknown'} <${c.fromAddress}>  |  *Subject:* ${c.subject}`,
    `*Conflict check:* clear (${c.partiesChecked} names checked against ${c.registerSize} register entries)`,
    `*Limitation:* ${lim.status}${lim.deadline ? ` | screen deadline ${lim.deadline} (${lim.daysLeft} days)` : ''} | rule: ${lim.rule}`,
    '',
    `*Summary:* ${brief.summary || ''}`,
    (brief.keyFacts || []).length ? `*Key facts:*\n• ${brief.keyFacts.join('\n• ')}` : '',
    (brief.missingInformation || []).length ? `*Missing:*\n• ${brief.missingInformation.join('\n• ')}` : '',
    questions.length ? `*Questions for the intake call:*\n• ${questions.join('\n• ')}` : '',
    `*Suggested reviewer:* ${brief.suggestedReviewer || 'Intake attorney'}`,
    flagged.length ? `:warning: *Advice-boundary flag:* ${flagged.length} line(s) read like legal advice. Review before using them with the client.` : '',
    '_AI-generated brief for internal review only. Not legal advice. Verify every fact and date before acting._',
  ].filter(Boolean).join('\n');

  const firstName = (c.fromName || '').split(' ')[0] || 'there';
  const ackText = settings.acknowledgementTemplate
    .replaceAll('{{firstName}}', firstName)
    .replaceAll('{{firmName}}', settings.firmName);

  return {
    json: {
      messageId: c.messageId,
      isTest: c.isTest,
      slackText,
      ackText,
      log: {
        received_at: c.receivedAt,
        from: c.fromAddress,
        subject: c.subject,
        matter_type: c.extracted.matterType,
        conflict: 'clear',
        limitation_status: lim.status,
        limitation_deadline: lim.deadline || '',
        priority,
        advice_flags: flagged.length,
        outcome: 'routed_to_review',
      },
    },
  };
});
